# Independent offline evidence validation; no storage calls, deletion or cleanup.
param([Parameter(Mandatory=$true)][string]$PublicDirectory,[Parameter(Mandatory=$true)][string]$PrivateDirectory,[ValidatePattern('^reader-independent-validation(?:-[a-z0-9-]+)?\.json$')][string]$OutputName='reader-independent-validation.json')
$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
$public=(Resolve-Path -LiteralPath $PublicDirectory).Path
$private=(Resolve-Path -LiteralPath $PrivateDirectory).Path
if(Test-Path -LiteralPath (Join-Path $public $OutputName)){throw 'Validation result already exists; use a new output name to preserve evidence'}
function Read([string]$Name){Get-Content -LiteralPath (Join-Path $public $Name) -Raw|ConvertFrom-Json}
$m=Read 'manifest.json';$f=Read 'reader-durable-facts.json';$r=Read 'reader-originals-final.json';$a=Read 'reader-audit-evidence.json';$crash=Read 'reader-crash.json';$seal=Read 'reader-seal.json';$envProof=Read 'reader-environment.json'
if($f.calls.Count -ne 31 -or $f.observations.Count -ne 31 -or $f.cost_allocations.Count -ne 31 -or $f.pins.Count -ne 3 -or $f.terminations.Count -ne 2 -or $f.counts.copies -ne 4 -or $f.counts.copy_operations -ne 0 -or $f.counts.disposition_dispatch -ne 0 -or $f.counts.provider_attempts -ne 0){throw 'Core evidence counts mismatch'}
foreach($call in $f.calls){if(@($f.observations|Where-Object {$_.call_id -eq $call.id -and $null -ne $_.invoked_at}).Count -ne 1 -or @($f.cost_allocations|Where-Object {$_.lifecycle_storage_call_id -eq $call.id}).Count -ne 1){throw 'Physical call/observation/cost bijection mismatch'}}
$readCalls=@($f.calls|Where-Object {$_.operation -eq 'READ_PINNED'})
if($readCalls.Count -ne 3 -or @($readCalls.reader_pin_id|Select-Object -Unique).Count -ne 3){throw 'Read replay created another physical call'}
foreach($call in $readCalls){$pin=@($f.pins|Where-Object {$_.id -eq $call.reader_pin_id});$obs=@($f.observations|Where-Object {$_.call_id -eq $call.id});if($pin.Count -ne 1 -or $pin[0].copy_id -ne $call.copy_id -or [DateTimeOffset]$pin[0].started_at -gt [DateTimeOffset]$call.started_at -or $obs[0].http_status -ne 200 -or $obs[0].failure -ne '' -or $obs[0].response_sha256 -ne $m.objects[0].sha256){throw 'Read began without its exact committed pin/native bytes'}}
if(@($f.pins|Where-Object {$_.id -eq $crash.pin.ID}).Count -ne 1 -or @($f.terminations|Where-Object {$_.pin_id -eq $crash.pin.ID}).Count -ne 0 -or @($f.terminations|Where-Object {$_.outcome -eq 'COMPLETED'}).Count -ne 1 -or @($f.terminations|Where-Object {$_.outcome -eq 'CANCELLATION_CONFIRMED'}).Count -ne 1){throw 'Owner stop evidence mismatch'}
foreach($name in @('LifecycleReaderAdmitted','LifecycleReaderTerminated','LifecycleStorageCallStarted','LifecycleStorageCallObserved')){$event=@($f.events|Where-Object {$_.event_type -eq $name});$audit=@($a.audits|Where-Object {$_.action -eq $name});$evidence=@($a.evidence|Where-Object {$_.title -eq $name});if($event.Count -ne 1 -or $audit.Count -ne 1 -or $evidence.Count -ne 1 -or $event[0].count -ne $audit[0].count -or $event[0].count -ne $evidence[0].count){throw 'Event/Audit/Evidence boundary mismatch'}}
foreach($original in $m.objects){$entry=@($r.objects|Where-Object {$_.copy.ID -eq $original.copy_id});$versions=@($r.inventories|Where-Object {$_.Namespace -eq $original.namespace}|ForEach-Object {$_.Versions}|Where-Object {$_.Key -eq $original.key -and $_.Version -eq $original.version_id});if($entry.Count -ne 1 -or $versions.Count -ne 1 -or $versions[0].DeleteMarker -or $entry[0].copy.ProviderVersion -ne $original.version_id -or $entry[0].copy.ContentSHA256 -ne $original.sha256 -or $entry[0].protection.LegalHold -ne $original.legal_hold -or $entry[0].protection.RetentionMode -ne $original.retention_mode){throw 'Original exact object/protection changed'};if($null -ne $original.retain_until -and [DateTimeOffset]$entry[0].protection.RetainUntil -ne [DateTimeOffset]$original.retain_until){throw 'Retention deadline changed'}}
if(@($r.inventories|ForEach-Object {$_.Versions}).Count -ne 4 -or $seal.native_reader_identity -ne 'DISABLED' -or $seal.windows_enabled -or $seal.gateway_payload -ne 'DENY_ALL' -or $seal.gateway_admin -ne 'DENY_ALL' -or $seal.gateway_delete -ne 'DENY_ALL'){throw 'Native inventory/seal mismatch'}
$binding=Read 'reader-source-binding.json'
if($binding.code_commit -notmatch '^[a-f0-9]{40}$'){throw 'Exact accepted code commit required'}
foreach($path in $envProof.source_hashes.PSObject.Properties){$psi=[Diagnostics.ProcessStartInfo]::new('git');$psi.WorkingDirectory=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path;$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.ArgumentList.Add('show');$psi.ArgumentList.Add($binding.code_commit+':'+$path.Name);$process=[Diagnostics.Process]::Start($psi);$stream=[IO.MemoryStream]::new();$process.StandardOutput.BaseStream.CopyTo($stream);$process.WaitForExit();$sha=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($stream.ToArray())).ToLowerInvariant();if($process.ExitCode -ne 0 -or $sha -ne $path.Value){throw 'Native source does not match its exact committed Git blob'}}
$secrets=[Collections.Generic.HashSet[string]]::new()
function Collect($v){if($null -eq $v){return};if($v -is [string]){return};if($v -is [array]){foreach($x in $v){Collect $x};return};foreach($prop in $v.PSObject.Properties){if($prop.Name -match '(Secret|Password|Access|AccessKey|PostgresDSN|Token)$' -and $prop.Value -is [string] -and $prop.Value.Length -ge 12){[void]$secrets.Add($prop.Value)}elseif($null -ne $prop.Value -and $prop.Value -isnot [ValueType]){Collect $prop.Value}}}
foreach($file in Get-ChildItem -LiteralPath $private -Filter '*.json' -Recurse -File){Collect (Get-Content -LiteralPath $file.FullName -Raw|ConvertFrom-Json)}
$files=@(Get-ChildItem -LiteralPath $public -Recurse -File)
foreach($file in $files){$body=[IO.File]::ReadAllText($file.FullName);foreach($secret in $secrets){if($body.Contains($secret)){throw 'Private credential found in public evidence'}}}
$result=@{result='PASS';validator='offline PowerShell independent from Go acceptance runner';accepted_code_commit=$binding.code_commit;native_calls=31;read_calls=3;observations=31;cost_allocations=31;reader_pins=3;confirmed_stops=2;unconfirmed_crashed_pin=1;original_versions_retained=4;native_delete=0;copy=0;cleanup=0;native_source_hashes='MATCH_EXACT_COMMIT';public_files_scanned=$files.Count;credential_scan='PASS'}
[IO.File]::WriteAllText((Join-Path $public $OutputName),($result|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
Write-Output "Reader independent evidence PASS; $($files.Count) public files credential scan PASS."
